-- Synthetic gas utility billing detail schema for local Oracle Free testing.
-- Grain: one row per billed service agreement and bill period.
-- All customer and service values are synthetic; no production data is used.
-- The 146 columns use VARCHAR2, NUMBER, and DATE types supported by the
-- local_db.py seed_data helper. The identity key is generated by Oracle.

WHENEVER SQLERROR EXIT SQL.SQLCODE

CREATE TABLE GAS_BILLING_DETAIL (
    BILLING_DETAIL_ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    ACCOUNT_NUMBER VARCHAR2(20),
    CUSTOMER_NUMBER VARCHAR2(20),
    SERVICE_AGREEMENT_NUMBER VARCHAR2(24),
    PREMISE_NUMBER VARCHAR2(24),
    SERVICE_POINT_ID VARCHAR2(32),
    BILLING_CYCLE_CODE VARCHAR2(12),
    BILL_NUMBER VARCHAR2(24),
    BILL_SEQUENCE_NUMBER NUMBER(6),
    BILL_STATUS VARCHAR2(20),
    BILL_TYPE VARCHAR2(20),
    BILL_ISSUE_DATE DATE,
    BILL_DUE_DATE DATE,
    BILL_PERIOD_START DATE,
    BILL_PERIOD_END DATE,
    PRIOR_BILL_NUMBER VARCHAR2(24),
    ADJUSTMENT_INDICATOR VARCHAR2(5),
    REBILL_INDICATOR VARCHAR2(5),
    CONSOLIDATED_BILL_INDICATOR VARCHAR2(5),
    INVOICE_CURRENCY_CODE VARCHAR2(3),
    CUSTOMER_TYPE_CODE VARCHAR2(20),
    CUSTOMER_CLASS_CODE VARCHAR2(20),
    CUSTOMER_FIRST_NAME VARCHAR2(60),
    CUSTOMER_MIDDLE_NAME VARCHAR2(60),
    CUSTOMER_LAST_NAME VARCHAR2(60),
    CUSTOMER_BUSINESS_NAME VARCHAR2(120),
    CUSTOMER_TAX_ID_MASKED VARCHAR2(20),
    CUSTOMER_CONTACT_NAME VARCHAR2(120),
    CUSTOMER_PRIMARY_PHONE VARCHAR2(24),
    CUSTOMER_ALTERNATE_PHONE VARCHAR2(24),
    CUSTOMER_EMAIL_ADDRESS VARCHAR2(120),
    CUSTOMER_LANGUAGE_CODE VARCHAR2(10),
    CUSTOMER_COMMUNICATION_PREFERENCE VARCHAR2(20),
    CUSTOMER_PAPERLESS_INDICATOR VARCHAR2(5),
    MAILING_ADDRESS_LINE_1 VARCHAR2(120),
    MAILING_ADDRESS_LINE_2 VARCHAR2(120),
    MAILING_CITY VARCHAR2(60),
    MAILING_REGION VARCHAR2(40),
    MAILING_POSTAL_CODE VARCHAR2(20),
    MAILING_COUNTRY_CODE VARCHAR2(3),
    SERVICE_ADDRESS_LINE_1 VARCHAR2(120),
    SERVICE_ADDRESS_LINE_2 VARCHAR2(120),
    SERVICE_CITY VARCHAR2(60),
    SERVICE_REGION VARCHAR2(40),
    SERVICE_POSTAL_CODE VARCHAR2(20),
    SERVICE_COUNTRY_CODE VARCHAR2(3),
    SERVICE_COUNTY VARCHAR2(60),
    SERVICE_LATITUDE NUMBER(10, 7),
    SERVICE_LONGITUDE NUMBER(10, 7),
    SERVICE_TERRITORY_CODE VARCHAR2(20),
    SERVICE_DISTRICT_CODE VARCHAR2(20),
    SERVICE_ROUTE_CODE VARCHAR2(20),
    SERVICE_PREMISE_TYPE VARCHAR2(20),
    SERVICE_OCCUPANCY_STATUS VARCHAR2(20),
    SERVICE_START_DATE DATE,
    SERVICE_END_DATE DATE,
    METER_NUMBER VARCHAR2(32),
    METER_TYPE_CODE VARCHAR2(20),
    METER_MANUFACTURER VARCHAR2(60),
    METER_MODEL VARCHAR2(60),
    METER_INSTALL_DATE DATE,
    METER_READ_START_DATE DATE,
    METER_READ_END_DATE DATE,
    METER_PREVIOUS_READ NUMBER(14, 3),
    METER_CURRENT_READ NUMBER(14, 3),
    METER_PREVIOUS_READ_CODE VARCHAR2(20),
    METER_CURRENT_READ_CODE VARCHAR2(20),
    METER_USAGE_FACTOR NUMBER(12, 6),
    METER_PRESSURE_FACTOR NUMBER(12, 6),
    METER_TEMPERATURE_FACTOR NUMBER(12, 6),
    METER_THERM_CONVERSION_FACTOR NUMBER(12, 6),
    METER_BILLED_THERMS NUMBER(14, 3),
    METER_ESTIMATED_READ_INDICATOR VARCHAR2(5),
    METER_STATUS_CODE VARCHAR2(20),
    METER_REGISTER_MULTIPLIER NUMBER(12, 4),
    RATE_SCHEDULE_CODE VARCHAR2(24),
    RATE_SCHEDULE_DESCRIPTION VARCHAR2(120),
    TARIFF_VERSION VARCHAR2(24),
    TARIFF_EFFECTIVE_DATE DATE,
    COMMODITY_TYPE_CODE VARCHAR2(20),
    RATE_CUSTOMER_CLASS VARCHAR2(20),
    BILLING_DETERMINANT_CODE VARCHAR2(24),
    GAS_SUPPLY_RATE NUMBER(14, 6),
    FIXED_MONTHLY_RATE NUMBER(14, 6),
    DISTRIBUTION_RATE NUMBER(14, 6),
    TRANSPORTATION_RATE NUMBER(14, 6),
    CAPACITY_RATE NUMBER(14, 6),
    DEMAND_RATE NUMBER(14, 6),
    MINIMUM_BILL_AMOUNT NUMBER(14, 2),
    PRICE_PLAN_CODE VARCHAR2(24),
    RATE_PERIOD_CODE VARCHAR2(20),
    PRIOR_BALANCE_AMOUNT NUMBER(14, 2),
    PAYMENTS_RECEIVED_AMOUNT NUMBER(14, 2),
    CREDITS_APPLIED_AMOUNT NUMBER(14, 2),
    DEPOSIT_APPLIED_AMOUNT NUMBER(14, 2),
    GAS_SUPPLY_CHARGE NUMBER(14, 2),
    DISTRIBUTION_CHARGE NUMBER(14, 2),
    CUSTOMER_CHARGE NUMBER(14, 2),
    METER_CHARGE NUMBER(14, 2),
    TRANSPORTATION_CHARGE NUMBER(14, 2),
    CAPACITY_CHARGE NUMBER(14, 2),
    DEMAND_CHARGE NUMBER(14, 2),
    LATE_PAYMENT_FEE NUMBER(14, 2),
    SERVICE_FEE NUMBER(14, 2),
    OTHER_CHARGES_AMOUNT NUMBER(14, 2),
    CITY_TAX_AMOUNT NUMBER(14, 2),
    COUNTY_TAX_AMOUNT NUMBER(14, 2),
    STATE_TAX_AMOUNT NUMBER(14, 2),
    FEDERAL_TAX_AMOUNT NUMBER(14, 2),
    CURRENT_CHARGES_AMOUNT NUMBER(14, 2),
    TOTAL_BILL_AMOUNT NUMBER(14, 2),
    TOTAL_AMOUNT_DUE NUMBER(14, 2),
    PAYMENT_METHOD_CODE VARCHAR2(24),
    PAYMENT_CHANNEL_CODE VARCHAR2(24),
    PAYMENT_PLAN_CODE VARCHAR2(24),
    PAYMENT_PLAN_STATUS VARCHAR2(20),
    PAYMENT_PROMISE_DATE DATE,
    LAST_PAYMENT_DATE DATE,
    LAST_PAYMENT_AMOUNT NUMBER(14, 2),
    DEPOSIT_HELD_AMOUNT NUMBER(14, 2),
    TAX_EXEMPT_INDICATOR VARCHAR2(5),
    TAX_EXEMPTION_CODE VARCHAR2(24),
    ADJUSTMENT_REASON_CODE VARCHAR2(24),
    ADJUSTMENT_AMOUNT NUMBER(14, 2),
    DISPUTE_STATUS_CODE VARCHAR2(20),
    DISPUTE_OPEN_DATE DATE,
    BUDGET_BILLING_INDICATOR VARCHAR2(5),
    BUDGET_BILLING_AMOUNT NUMBER(14, 2),
    DISCONNECTION_NOTICE_DATE DATE,
    ACCOUNT_STATUS_CODE VARCHAR2(20),
    CREDIT_RISK_CODE VARCHAR2(20),
    COLLECTION_STATUS_CODE VARCHAR2(20),
    SERVICE_PRIORITY_CODE VARCHAR2(20),
    LOW_INCOME_PROGRAM_CODE VARCHAR2(24),
    ASSISTANCE_CREDIT_AMOUNT NUMBER(14, 2),
    GREEN_ENERGY_PROGRAM_CODE VARCHAR2(24),
    RENEWABLE_GAS_INDICATOR VARCHAR2(5),
    CUSTOMER_SEGMENT_CODE VARCHAR2(24),
    BILL_DELIVERY_STATUS VARCHAR2(20),
    BILL_PRINT_DATE DATE,
    BILL_EXPORT_BATCH_ID VARCHAR2(36),
    SOURCE_SYSTEM_CODE VARCHAR2(24),
    SOURCE_RECORD_ID VARCHAR2(48),
    RECORD_CREATED_DATE DATE,
    RECORD_UPDATED_DATE DATE,
    DATA_QUALITY_STATUS VARCHAR2(20)
);

COMMENT ON TABLE GAS_BILLING_DETAIL IS
    'Synthetic utility billing detail; one row per service agreement and bill period.';
COMMENT ON COLUMN GAS_BILLING_DETAIL.BILLING_DETAIL_ID IS
    'Oracle-generated unique key for each synthetic billing detail row.';
